import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, createIssue, inviteAndJoin, uniqueName } from './helpers';

test.describe(`team member: comment on an issue to discuss it, and edit or delete only my own comments`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
    await createWorkspace(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a comment is posted, it appears in the issue's thread for all teammates within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await inviteAndJoin(pageA, pageB);

    const title = uniqueName('issue');
    const body = uniqueName('comment');
    await createIssue(pageA, { title });

    const cardA = pageA.getByTestId('item-issue').filter({ hasText: title });
    await expect(cardA).toBeVisible({ timeout: 10_000 });
    await cardA.click();
    await pageA.getByTestId('field-body').fill(body);
    await pageA.getByTestId('action-add_comment').click();
    await expect(pageA.getByTestId('item-comment').filter({ hasText: body })).toBeVisible({ timeout: 5_000 });

    // Teammate B opens the same issue and sees the comment in the thread within 5s.
    const cardB = pageB.getByTestId('item-issue').filter({ hasText: title });
    await expect(cardB).toBeVisible({ timeout: 5_000 });
    await cardB.click();
    await expect(pageB.getByTestId('item-comment').filter({ hasText: body })).toBeVisible({ timeout: 5_000 });

    await ctxA.close();
    await ctxB.close();
  });

  test(`a member can only edit or delete comments they authored; attempts on other members' comments are rejected`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await inviteAndJoin(pageA, pageB);

    const title = uniqueName('issue');
    const body = uniqueName('comment');
    await createIssue(pageA, { title });

    const cardA = pageA.getByTestId('item-issue').filter({ hasText: title });
    await expect(cardA).toBeVisible({ timeout: 10_000 });
    await cardA.click();
    await pageA.getByTestId('field-body').fill(body);
    await pageA.getByTestId('action-add_comment').click();

    // Author A sees edit/delete controls on their own comment.
    const commentA = pageA.getByTestId('item-comment').filter({ hasText: body });
    await expect(commentA).toBeVisible({ timeout: 5_000 });
    // The author's own controls appear once authorship resolves against the
    // executor identity, which can trail the comment render by a beat - wait it
    // out rather than snapshot it.
    await expect(commentA.getByTestId('action-delete_comment')).toBeVisible({ timeout: 15_000 });

    // Member B (a different author) sees the comment but NOT the edit/delete
    // controls — authorship gates mutation, so B's attempts are rejected.
    const cardB = pageB.getByTestId('item-issue').filter({ hasText: title });
    await expect(cardB).toBeVisible({ timeout: 5_000 });
    await cardB.click();
    const commentB = pageB.getByTestId('item-comment').filter({ hasText: body });
    await expect(commentB).toBeVisible({ timeout: 5_000 });
    await expect(commentB.getByTestId('action-delete_comment')).toHaveCount(0);
    await expect(commentB.getByTestId('action-edit_comment')).toHaveCount(0);

    await ctxA.close();
    await ctxB.close();
  });
});
